<template>
  <div class="wrap">
    <div class="progress">
      <ve-progress
          :progress="progress"
          line="butt"
          :color="emptyColor"
          empty-color="#324c7e"
          thickness="90"
          emptyThickness="20"
          :size="180"
          lineMode="in-over"
          :legend="(time === 5 ? 0.1 : 5 - time)"
          fontSize="50px"
          fontColor="#f1f1f1"
          :legend-formatter="({ currentValue }) => `${currentValue}s`"
      >
      </ve-progress>
    </div>
  </div>
</template>

<script>

export default {
  name: "CuffProgress",
  computed: {
    progress() {
      return (this.time * 100) / 5;
    },
  },
  data() {
    return {
      time: 0,
      emptyColor: {
        radial: true,
        colors: [
          {
            color: "#7579ff",
            offset: "0",
            opacity: "0.1",
          },
          {
            color: "#7579ff",
            offset: "100",
            opacity: 0.5,
          },
        ],
      },
      emptyColorFill: {
        radial: true,
        colors: [
          {
            color: "#3260FC",
            offset: "0",
            opacity: 0,
          },
          {
            color: "#3260FC",
            offset: "100",
            opacity: 0.1,
          },
        ],
      },
    }
  },
}
</script>
<style lang="scss">
.progress {
  margin-bottom: 50px;
}

.wrap {
  width: 100vw;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-end;
}
</style>